def count_words(strings: list):
    """Count the occurrences of each word in a list of strings, case insensitively.

    Args:
        strings: A list of strings.

    Returns:
        A dictionary with words as keys (in lowercase) and their counts as values.
    """
    word_count = {}

    for string in strings:
        words = string.split()
        for word in words:
            # Process word to lowercase
            word_lower = word.lower()
            if word_lower in word_count:
                word_count[word_lower] += 1
            else:
                word_count[word_lower] = 1

    return word_count

