def find_anagram_substring(s1: str, s2: str) -> int:
    from collections import Counter

    len_s1 = len(s1)
    len_s2 = len(s2)

    if len_s1 > len_s2:
        return -1

    s1_counter = Counter(s1)
    window_counter = Counter(s2[:len_s1])

    for i in range(len_s2 - len_s1 + 1):
        if i > 0:
            # Slide the window: remove previous character, add new character
            prev_char = s2[i-1]
            new_char = s2[i+len_s1-1]
            window_counter[prev_char] -= 1
            if window_counter[prev_char] == 0:
                del window_counter[prev_char]
            window_counter[new_char] += 1

        if window_counter == s1_counter:
            return i

    return -1

