def longest_sequence_length(n, S):
    """
    Find the length of the longest sequence of consecutive integers
    from the set {1, 2, ..., n} that sums up to S.
    """
    # Use the sum of arithmetic progression to find the length
    for length in range(n, 0, -1):
        total_sum = (length * (length + 1)) // 2
        if total_sum > S:
            continue
        if (S - total_sum) % length == 0 and (S - total_sum) // length < n:
            start = (S - total_sum) // length + 1
            if start > 0 and (start + length - 1) <= n:
                return length
    return 0

