from typing import List

def four_sum(arr: List[int], target: int) -> List[List[int]]:
    """
    Returns all unique quadruplets from the array that sum up to the target sum.
    """
    arr.sort()
    quadruplets = []
    length = len(arr)

    for i in range(length - 3):
        if i > 0 and arr[i] == arr[i - 1]: continue
        for j in range(i + 1, length - 2):
            if j > i + 1 and arr[j] == arr[j - 1]: continue
            left, right = j + 1, length - 1
            while left < right:
                total = arr[i] + arr[j] + arr[left] + arr[right]
                if total == target:
                    quadruplets.append([arr[i], arr[j], arr[left], arr[right]])
                    while left < right and arr[left] == arr[left + 1]:
                        left += 1
                    while left < right and arr[right] == arr[right - 1]:
                        right -= 1
                    left += 1
                    right -= 1
                elif total < target:
                    left += 1
                else:
                    right -= 1

    return quadruplets

