def sum_of_multiples_of_divisors(num):
    """
    Returns the sum of all the positive integers less than `num` that are multiples of its divisors.
    """
    if num <= 1:
        return 0

    divisors = [i for i in range(1, num) if num % i == 0]
    multiples = set()

    for divisor in divisors:
        multiples.update(range(divisor, num, divisor))

    return sum(multiples)

