def mod_expo(base: int, exponent: int, mod: int) -> int:
    if exponent < 0:
        raise ValueError("Exponent must be positive.")
    result = 1
    base = base % mod

    while exponent > 0:
        if (exponent % 2) == 1:
            result = (result * base) % mod
        exponent = exponent >> 1
        base = (base * base) % mod

    return result

