def find_unique_elements(list_of_lists):
    """
    Returns a list of elements that appear exactly once in the entire list of lists.

    :param list_of_lists: List of lists
    :return: List of unique elements
    """
    # Create a dictionary to count the occurrence of each element
    element_count = {}

    for sublist in list_of_lists:
        for item in sublist:
            if item in element_count:
                element_count[item] += 1
            else:
                element_count[item] = 1

    # Extract elements that appear exactly once
    unique_elements = [item for item, count in element_count.items() if count == 1]

    return unique_elements

