def sum_of_unique_prime_factors(n):
    """
    Returns the sum of all unique prime factors of n.
    """
    if n <= 1:
        return 0

    prime_factors = set()
    divisor = 2
    while n > 1:
        while n % divisor == 0:
            prime_factors.add(divisor)
            n //= divisor
        divisor += 1
        if divisor * divisor > n and n > 1:
            prime_factors.add(n)
            break

    return sum(prime_factors)

def findTriplets(arr, target):
    """
    Returns True if there exists a triplet in the array which sums up to the target sum.
    """
    n = len(arr)
    arr.sort()

    for i in range(n-2):
        left = i + 1
        right = n - 1
        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]
            if current_sum == target:
                return True
            elif current_sum < target:
                left += 1
            else:
                right -= 1
    return False

