def longest_same_parity_subarray(arr):
    """
    Returns the length of the longest contiguous subarray where all elements have the same parity.
    """
    if not arr:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, len(arr)):
        if (arr[i] % 2) == (arr[i-1] % 2):
            current_length += 1
        else:
            current_length = 1

        if current_length > max_length:
            max_length = current_length

    return max_length

