def generatePascalsTriangle(n):
    """
    Generates Pascal’s triangle of height n and returns it as a newline-separated string
    where numbers in each row are separated by a single space.
    """
    if n <= 0:
        return ""

    result = []
    for i in range(n):
        row = [1] * (i + 1)
        for j in range(1, i):
            row[j] = result[i-1][j-1] + result[i-1][j]
        result.append(row)

    return "\n".join(" ".join(map(str, row)) for row in result)

# Example usage:
# print(generatePascalsTriangle(5))

