def is_sorted_and_rotated(nums):
    """
    Check if the given array was originally sorted in an increasing order 
    and then possibly rotated.
    """
    n = len(nums)
    if n <= 1:
        return True

    count = 0
    for i in range(n):
        if nums[i] > nums[(i + 1) % n]:
            count += 1
        if count > 1:
            return False
    return True

