def process_transactions(users, transactions):
    # Create a dictionary for quick access to user balances
    user_balances = {user['name']: user['balance'] for user in users}

    for transaction in transactions:
        parts = transaction.split()
        if parts[0] == "DEPOSIT":
            _, username, amount = parts
            user_balances[username] += float(amount)
        elif parts[0] == "WITHDRAW":
            _, username, amount = parts
            if user_balances[username] >= float(amount):
                user_balances[username] -= float(amount)
        elif parts[0] == "TRANSFER":
            _, from_user, to_user, amount = parts
            if user_balances[from_user] >= float(amount):
                user_balances[from_user] -= float(amount)
                user_balances[to_user] += float(amount)

    # Update the original users list with the new balances
    for user in users:
        user['balance'] = user_balances[user['name']]

    # Sort users by name
    users.sort(key=lambda user: user['name'])

    return users

