def count_distinct_prime_factors(n):
    """
    Returns the number of distinct prime factors of the given integer n.
    """
    if n < 2:
        return 0

    prime_factors = set()
    i = 2
    while i * i <= n:
        while n % i == 0:
            prime_factors.add(i)
            n //= i
        i += 1
    if n > 1:
        prime_factors.add(n)

    return len(prime_factors)

