def floyd_warshall(graph):
    """
    Floyd-Warshall algorithm to find the shortest paths between all pairs of nodes.
    :param graph: 2D list representing the adjacency matrix of a graph
    :return: 2D list representing the shortest path distances between all pairs of nodes
    """
    num_vertices = len(graph)
    dist = [[float('inf')] * num_vertices for _ in range(num_vertices)]

    for i in range(num_vertices):
        for j in range(num_vertices):
            if i == j:
                dist[i][j] = 0
            elif graph[i][j] != 0:
                dist[i][j] = graph[i][j]

    for k in range(num_vertices):
        for i in range(num_vertices):
            for j in range(num_vertices):
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    return dist

