def euler_totient(n: int) -> int:
    """
    Computes the value of Euler's Totient Function for a given integer n.
    """
    if n == 1:
        return 1

    result = n
    p = 2
    while p * p <= n:
        # Check if p is a divisor of n
        if n % p == 0:
            # If yes, then it means p is a prime factor of n
            while n % p == 0:
                n = n // p
            result -= result // p
        p += 1

    # If n has a prime factor greater than sqrt(n)
    if n > 1:
        result -= result // n

    return result

