def evaluate_postfix(expression: str) -> float:
    stack = []

    for token in expression.split():
        if token.isdigit() or (token[1:].isdigit() and token[0] == '-'):
            stack.append(float(token))
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                stack.append(a / b)

    return stack.pop()

