def is_parentheses_balanced(expression: str) -> bool:
    """
    Checks if the parentheses in the expression are balanced and properly nested.
    """
    stack = []
    for char in expression:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()

    return len(stack) == 0

