def longestUniqueSubstring(s: str) -> int:
    """
    Returns the length of the longest substring with all unique characters.
    """
    char_index_map = {}
    longest = 0
    start = 0

    for i, char in enumerate(s):
        if char in char_index_map and char_index_map[char] >= start:
            start = char_index_map[char] + 1
        char_index_map[char] = i
        longest = max(longest, i - start + 1)

    return longest

def rotate_180(matrix):
    """
    Rotates the given N x N matrix by 180 degrees.
    """
    n = len(matrix)
    for i in range(n):
        for j in range(n):
            if i * n + j < (n * n) // 2:
                opp_i, opp_j = n - 1 - i, n - 1 - j
                matrix[i][j], matrix[opp_i][opp_j] = matrix[opp_i][opp_j], matrix[i][j]

    return matrix

