def count_fruits(basket):
    """
    Takes a list of strings representing different fruits in a basket
    and returns a dictionary with each fruit as a key and the number
    of times it appears in the list as the corresponding value. The
    comparison is case-insensitive.
    """
    fruit_count = {}
    for fruit in basket:
        fruit_lower = fruit.lower()
        if fruit_lower in fruit_count:
            fruit_count[fruit_lower] += 1
        else:
            fruit_count[fruit_lower] = 1
    return fruit_count

