def is_water_flow_possible(pipeline: str) -> bool:
    """
    Determines if there is a continuous path of water flow from any 'A' to any 'T' in the pipeline.
    """
    # Get the index of all 'A's and 'T's in the pipeline
    sources = {i for i, char in enumerate(pipeline) if char == 'A'}
    targets = {i for i, char in enumerate(pipeline) if char == 'T'}

    # Define the set of blockers
    blockers = {'B'}

    for source in sources:
        # We'll use a stack for DFS
        stack = [source]
        visited = set()

        while stack:
            current = stack.pop()

            if current in targets:
                return True

            if current in visited:
                continue

            visited.add(current)

            # Explore neighbors (left and right)
            if current + 1 < len(pipeline) and pipeline[current+1] not in blockers:
                stack.append(current + 1)

            if current - 1 >= 0 and pipeline[current-1] not in blockers:
                stack.append(current - 1)

    return False

