def longest_repeated_substring(s):
    """
    Returns the length of the longest substring consisting of the same character.
    """
    if not s:
        return 0

    max_len = 1
    current_len = 1

    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            current_len += 1
        else:
            max_len = max(max_len, current_len)
            current_len = 1

    max_len = max(max_len, current_len)  # check for the last sequence
    return max_len

