def int_to_binary(n: int, format: str = 'compact') -> str:
    if not isinstance(n, int) or n < 0:
        raise ValueError("Input must be a non-negative integer.")
    if format not in ['compact', 'readable']:
        raise ValueError("Invalid format. Format must be either 'compact' or 'readable'.")

    binary = bin(n)[2:]
    if format == 'compact':
        return binary

    readable_binary = ''
    for i in range(0, len(binary), 4):
        readable_binary += binary[i:i+4] + ' '
    return readable_binary.strip()

