def longestPalindromicSubsequence(s: str) -> int:
    """
    Returns the length of the longest palindromic subsequence in the given string s.
    """
    n = len(s)

    # Create a 2D array to store lengths of longest palindromic subsequences.
    dp = [[0] * n for _ in range(n)]

    # All sub-strings of length 1 are palindromes of length 1.
    for i in range(n):
        dp[i][i] = 1

    # Build the table.
    for cl in range(2, n + 1):
        for i in range(n - cl + 1):
            j = i + cl - 1
            if s[i] == s[j] and cl == 2:
                dp[i][j] = 2
            elif s[i] == s[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i][j - 1], dp[i + 1][j])

    return dp[0][n - 1]

