def factorial_iterative(n):
    """
    Returns the factorial of a given number n using an iterative approach.
    """
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers")
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

