def fizz_buzz(n):
    """
    Generates a list of strings based on the FizzBuzz pattern for numbers from 1 to n.

    Args:
    n (int): The upper limit of the range starting from 1.

    Returns:
    List[str]: A list of strings based on the specified FizzBuzz rules.
    """
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def count_sublists_with_target_sum(lst, target_sum):
    """
    Returns the count of distinct, non-empty contiguous sublists that have a sum equal to target_sum.
    """
    count = 0
    for start in range(len(lst)):
        current_sum = 0
        for end in range(start, len(lst)):
            current_sum += lst[end]
            if current_sum == target_sum:
                count += 1
    return count

