def find_duplicates(nums):
    """
    Returns a list of duplicate elements from the input list 'nums'.
    """
    duplicate_check = set()
    duplicates = set()

    for num in nums:
        if num in duplicate_check:
            duplicates.add(num)
        else:
            duplicate_check.add(num)

    return list(duplicates)

