reference_solution:
def is_monotonic_string(s):
    """
    Returns True if the string s is either monotonically increasing or decreasing, False otherwise.
    """
    if not s:
        return True  # An empty string is considered monotonically increasing and decreasing

    increasing = True
    decreasing = True

    for i in range(1, len(s)):
        if s[i] > s[i-1]:
            decreasing = False
        elif s[i] < s[i-1]:
            increasing = False

    return increasing or decreasing

def length_of_longest_substring(s):
    """
    This function returns the length of the longest substring without repeating characters.
    :param s: String input
    :return: Integer length of the longest substring without repeating characters
    """
    start = 0
    max_length = 0
    used_chars = {}

    for i, char in enumerate(s):
        if char in used_chars and start <= used_chars[char]:
            start = used_chars[char] + 1
        else:
            max_length = max(max_length, i - start + 1)

        used_chars[char] = i

    return max_length

from typing import List

def generate_pascals_triangle(n: int) -> List[List[int]]:
    if n == 0:
        return []

    triangle = [[1]]

    for row_num in range(1, n):
        row = [1]
        last_row = triangle[row_num - 1]
        for j in range(1, row_num):
            row.append(last_row[j - 1] + last_row[j])
        row.append(1)
        triangle.append(row)

    return triangle

