def min_operations_to_make_equal(s1, s2):
    """
    Returns the minimum number of operations required to make s1 and s2 equal.
    An operation consists of removing one character from either string.
    """
    m, n = len(s1), len(s2)

    # Create a table to store the length of longest common subsequence of substrings
    # lcs_length[i][j] will be the length of lcs of s1[0..i-1] & s2[0..j-1]
    lcs_length = [[0] * (n + 1) for _ in range(m + 1)]

    # Build the lcs_length table from bottom right corner
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                lcs_length[i][j] = lcs_length[i - 1][j - 1] + 1
            else:
                lcs_length[i][j] = max(lcs_length[i - 1][j], lcs_length[i][j - 1])

    # The number of operations needed is the sum of deletions needed
    return (m - lcs_length[m][n]) + (n - lcs_length[m][n])

