def is_perfect_square(x):
    """
    Returns True if x is a perfect square, otherwise False.
    Handles edge cases for zero and negative numbers.
    """
    if x < 0:
        return False
    if x == 0:
        return True

    left, right = 1, x
    while left <= right:
        mid = (left + right) // 2
        if mid * mid == x:
            return True
        elif mid * mid < x:
            left = mid + 1
        else:
            right = mid - 1
    return False

