def is_sorted_and_unique(words):
    """
    Returns True if the given tuple of words is sorted in ascending order
    and contains only unique words. Otherwise, returns False.
    """
    # Check for uniqueness
    if len(set(words)) != len(words):
        return False

    # Check for ascending order
    for i in range(len(words) - 1):
        if words[i] > words[i + 1]:
            return False

    return True

