def longest_subarray_with_sum_at_most_x(arr, x):
    max_length = 0
    current_sum = 0
    start_index = 0

    for end_index in range(len(arr)):
        current_sum += arr[end_index]

        while current_sum > x and start_index <= end_index:
            current_sum -= arr[start_index]
            start_index += 1

        if current_sum <= x:
            max_length = max(max_length, end_index - start_index + 1)

    return max_length

