def calculate_average(numbers):
    """
    Calculates the average of a list of numbers. 
    Returns None if the list is empty or contains non-numeric values.

    :param numbers: List of numbers
    :return: The average of the list of numbers or None
    """
    if not numbers:
        return None

    total = 0
    count = 0

    for num in numbers:
        if isinstance(num, (int, float)):
            total += num
            count += 1
        else:
            return None

    if count == 0:
        return None

    return total / count

def rotated_array_search(arr, target):
    """
    Searches for a target value within a rotated sorted array and returns its index if found.
    If the target is not found, returns -1.
    """
    if not arr:
        return -1

    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] == target:
            return mid

        if arr[left] <= arr[mid]:  # Left half is sorted
            if arr[left] <= target < arr[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:  # Right half is sorted
            if arr[mid] < target <= arr[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

