def min_operations(word_a: str, word_b: str) -> int:
    """
    Computes the minimum number of operations required to transform word_a into word_b.
    An operation is defined as insertion, deletion, or substitution of a single character.
    """
    n, m = len(word_a), len(word_b)
    # dp[i][j] will hold the minimum distance to convert word_a[0:i] to word_b[0:j]
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Initialize dp for transforming from/to empty string
    for i in range(1, n + 1):
        dp[i][0] = i  # Cost of deletions
    for j in range(1, m + 1):
        dp[0][j] = j  # Cost of insertions

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if word_a[i - 1] == word_b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]  # No operation needed if characters are the same
            else:
                dp[i][j] = min(dp[i - 1][j] + 1,    # Deletion
                               dp[i][j - 1] + 1,    # Insertion
                               dp[i - 1][j - 1] + 1)  # Substitution

    return dp[n][m]

