from collections import deque, defaultdict

def detect_fraud(transactions, time_frame, limit):
    fraudulent_accounts = set()
    account_transactions = defaultdict(deque)

    for account_id, amount, timestamp in transactions:
        if amount < 0:
            fraudulent_accounts.add(account_id)

        account_transactions[account_id].append((amount, timestamp))

        current_sum = 0
        valid_transactions = deque()

        while account_transactions[account_id]:
            t_amount, t_timestamp = account_transactions[account_id].popleft()
            if t_timestamp >= timestamp - time_frame:
                valid_transactions.append((t_amount, t_timestamp))
                current_sum += t_amount

        account_transactions[account_id] = valid_transactions

        if current_sum > limit:
            fraudulent_accounts.add(account_id)

    return sorted(fraudulent_accounts)

