def char_count(s):
    """
    Returns a dictionary where keys are characters from the string (case-insensitive),
    and values are the count of their occurrences in the string.
    """
    s = s.lower()
    count_dict = {}
    for char in s:
        if char in count_dict:
            count_dict[char] += 1
        else:
            count_dict[char] = 1
    return count_dict

