def lexicographically_smallest_subsequence(s, k):
    """
    Returns the lexicographically smallest subsequence of length k from string s.
    """
    stack = []
    n = len(s)

    for i, char in enumerate(s):
        while stack and len(stack) + (n - i) > k and stack[-1] > char:
            stack.pop()
        if len(stack) < k:
            stack.append(char)

    return ''.join(stack)

