def majority_element(nums):
    """
    Returns the majority element in the array, which is the element that appears more than ⌊n/2⌋ times.
    Assumes that the array is non-empty and the majority element always exists in the array.
    """
    candidate = None
    count = 0

    for num in nums:
        if count == 0:
            candidate = num
        if num == candidate:
            count += 1
        else:
            count -= 1

    return candidate

