import heapq

def shortest_paths(num_nodes, connections):
    if num_nodes == 0:
        return []

    # Create adjacency list
    graph = {i: [] for i in range(num_nodes)}
    for u, v, w in connections:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Use Dijkstra's algorithm to find shortest paths from node 0
    distances = {i: float('inf') for i in range(num_nodes)}
    distances[0] = 0
    priority_queue = [(0, 0)]  # (distance, node)

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    # Prepare result list
    result = [distances[i] if distances[i] != float('inf') else -1 for i in range(num_nodes)]
    return result

