def find_max_elements_and_sort(tuples_list):
    """
    Takes a list of tuples as input, finds the maximum element in each tuple,
    and returns a new list with these maximum elements, arranged in decreasing order.
    """
    max_elements = [max(tup) for tup in tuples_list]

    # Implementing a simple bubble sort to sort in descending order
    n = len(max_elements)
    for i in range(n):
        for j in range(0, n-i-1):
            if max_elements[j] < max_elements[j+1]:
                max_elements[j], max_elements[j+1] = max_elements[j+1], max_elements[j]

    return max_elements

def roman_to_int(s: str) -> int:
    """
    Convert a Roman numeral string to an integer.
    """
    roman_to_integer = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000
    }
    total = 0
    prev_value = 0

    for char in reversed(s):
        current_value = roman_to_integer[char]
        if current_value < prev_value:
            total -= current_value
        else:
            total += current_value
        prev_value = current_value

    return total

