def word_break(text, wordDict):
    """
    Determine if the text can be segmented into a space-separated sequence
    of one or more dictionary words.
    """
    dp = [False] * (len(text) + 1)
    dp[0] = True  # An empty string can always be segmented

    for i in range(1, len(text) + 1):
        for j in range(i):
            if dp[j] and text[j:i] in wordDict:
                dp[i] = True
                break

    return dp[len(text)]

