def find_smallest_with_index(numbers):
    """
    Returns a tuple containing the smallest number and its index in the given list of numbers.
    If the list is empty, returns (None, None).
    """
    if not numbers:
        return (None, None)

    smallest_num = numbers[0]
    smallest_index = 0

    for index, num in enumerate(numbers[1:], start=1):
        if num < smallest_num:
            smallest_num = num
            smallest_index = index

    return (smallest_num, smallest_index)

