def is_prime(n):
    """
    Check if a given integer n is a prime number.

    Parameters:
    n (int): The integer to check.

    Returns:
    bool: True if n is a prime number, otherwise False.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

