def factorial(n):
    """
    Returns the factorial of a given number n using recursion.

    Parameters:
    n (int): A non-negative integer to find the factorial of

    Returns:
    int: Factorial of the given number n
    """
    if n == 0:
        return 1
    else:
        return n * factorial(n - 1)

