def count_k_complement_pairs(arr, k):
    """
    Returns the number of unique pairs (x, y) in the array that satisfy x + y = k.
    """
    num_count = {}
    unique_pairs = set()

    for num in arr:
        complement = k - num
        if complement in num_count:
            # Ensure each pair is counted only once
            unique_pairs.add(tuple(sorted((num, complement))))
        num_count[num] = num_count.get(num, 0) + 1

    return len(unique_pairs)

