def group_strings_by_vowel_ending_count(strings):
    """
    Groups strings by the number of times they end with a vowel.

    Parameters:
    strings (list of str): The list of strings to be processed.

    Returns:
    dict: A dictionary where each key is an integer representing the number of times a string 
          in the list ends with a vowel, and the value is a list of strings that end with a vowel 
          and occur the number of times equal to the corresponding key.
    """
    vowels = 'aeiouAEIOU'
    count_dict = {}

    for string in strings:
        if string and string[-1] in vowels:
            count = strings.count(string)
            if count not in count_dict:
                count_dict[count] = []
            if string not in count_dict[count]:
                count_dict[count].append(string)

    return count_dict

