def largest_integer_whose_square_is_less_than_or_equal_to(n):
    """
    Returns the largest integer whose square is less than or equal to n.
    """
    if n < 0:
        return None

    largest_int = 0
    while (largest_int + 1) * (largest_int + 1) <= n:
        largest_int += 1
    return largest_int

