def two_sum(nums, k):
    """
    Returns the indices of the two numbers in the list that add up to the target sum `k`.
    """
    num_map = {}
    for index, num in enumerate(nums):
        complement = k - num
        if complement in num_map:
            return [num_map[complement], index]
        num_map[num] = index
    return None

