def atm_machine(transactions):
    """
    Simulates an ATM machine that processes deposits and withdrawals.

    Parameters:
    transactions (list): A list of tuples where each tuple contains a transaction 
                         type ('deposit' or 'withdraw') and an amount.

    Returns:
    int: The final balance after processing all transactions.
    """
    balance = 0  # Initial balance is zero

    for transaction in transactions:
        trans_type, amount = transaction
        if trans_type == 'deposit':
            balance += amount
        elif trans_type == 'withdraw':
            if amount <= balance:
                balance -= amount
            else:
                print("Error: Insufficient funds for withdrawal of ${}".format(amount))
        else:
            print("Error: Invalid transaction type '{}'".format(trans_type))

    return balance

