def is_possible(n: int) -> bool:
    """
    Determines if it's possible to obtain the number `n` starting from 1 using 
    only multiplication and division by 2 and 3 any number of times.
    """
    while n % 2 == 0:
        n //= 2
    while n % 3 == 0:
        n //= 3
    return n == 1

