def sum_of_divisors(n):
    """
    Returns the sum of all divisors of n, excluding n itself.
    """
    if n < 1:
        return 0

    sum_divisors = 0
    for i in range(1, n):
        if n % i == 0:
            sum_divisors += i
    return sum_divisors

import builtins

def transformed_open(path: str, transformations: list) -> str:
    with open(path, 'r') as file:
        content = file.read()

    for transformation in transformations:
        # Skip transformations that do not modify string content
        if transformation not in dir(str):
            continue

        # Get the built-in function
        transform_func = getattr(builtins.str, transformation, None)

        if transformation == 'replace':
            content = content.replace(' ', '-')
            continue

        if transform_func:
            content = transform_func(content)

    return content

