def most_frequent_element(lst):
    """
    This function finds the most frequent element in a list.
    If there are multiple elements with the same highest frequency,
    it returns the smallest of them.
    """
    frequency = {}
    for item in lst:
        frequency[item] = frequency.get(item, 0) + 1

    max_freq = max(frequency.values())
    most_freq_elements = [element for element, freq in frequency.items() if freq == max_freq]

    # Return the smallest of the most frequent elements
    return min(most_freq_elements)

