def nth_fibonacci(n: int) -> int:
    """
    Returns the n-th Fibonacci number.
    """
    if n == 0:
        return 0
    elif n == 1:
        return 1

    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

def num_decodings(s: str) -> int:
    if not s or s[0] == '0':
        return 0

    n = len(s)
    dp = [0] * (n + 1)
    dp[0] = 1  # An empty string has one way to be decoded

    for i in range(1, n + 1):
        # If the current character is not '0', it can contribute to single digit decode
        if s[i - 1] != '0':
            dp[i] += dp[i - 1]

        # If the two-character string formed with the previous character is between 10 and 26, it can contribute to a double-digit decode
        if i > 1 and '10' <= s[i - 2:i] <= '26':
            dp[i] += dp[i - 2]

    return dp[n]

