def longest_subarray_with_k_distinct(nums, k):
    """
    Returns the length of the longest subarray with exactly k distinct integers.
    """
    from collections import defaultdict

    if not nums or k == 0 or k > len(set(nums)):
        return 0

    max_length = 0
    left = 0
    freq = defaultdict(int)
    distinct_count = 0

    for right in range(len(nums)):
        if freq[nums[right]] == 0:
            distinct_count += 1
        freq[nums[right]] += 1

        while distinct_count > k:
            freq[nums[left]] -= 1
            if freq[nums[left]] == 0:
                distinct_count -= 1
            left += 1

        if distinct_count == k:
            max_length = max(max_length, right - left + 1)

    return max_length

