reference_solution:
def fizzbuzz_adjacent(n: int):
    """
    Generate a modified FizzBuzz sequence and count the occurrences of 'Fizz', 'Buzz', and 'FizzBuzz'.

    Args:
    n (int): The end number (inclusive) in the range starting from 1.

    Returns:
    Tuple[List[Union[int, str]], Dict[str, int]]: A tuple containing the modified list and a dictionary of counts.
    """

    result = []
    counts = {"Fizz": 0, "Buzz": 0, "FizzBuzz": 0}

    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
            counts["FizzBuzz"] += 1
        elif i % 3 == 0:
            result.append("Fizz")
            counts["Fizz"] += 1
        elif i % 5 == 0:
            result.append("Buzz")
            counts["Buzz"] += 1
        else:
            result.append(i)

    return result, counts

def longest_two_char_substring(s: str) -> str:
    if len(s) < 2:
        return ""

    start = 0
    max_length = 0
    max_substr = ""
    char_count = {}

    for end, char in enumerate(s):
        char_count[char] = char_count.get(char, 0) + 1

        while len(char_count) > 2:
            char_count[s[start]] -= 1
            if char_count[s[start]] == 0:
                del char_count[s[start]]
            start += 1

        current_length = end - start + 1
        if current_length > max_length:
            max_length = current_length
            max_substr = s[start:end + 1]

    return max_substr

