from typing import List

def can_form_triangle(arr: List[int]) -> str:
    """
    Determines if there are any three numbers in the array that can form a triangle.
    """
    arr.sort()
    for i in range(len(arr) - 2):
        if arr[i] + arr[i + 1] > arr[i + 2]:
            return "YES"
    return "NO"

