def find_unique_numbers(nums):
    """
    Returns a list containing only the elements that appear exactly once in the input list.
    """
    count = {}
    for num in nums:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    unique_nums = [num for num in nums if count[num] == 1]

    return unique_nums

def transform_string(s):
    """
    Transforms a string such that:
    - Each letter is replaced by the next one in the alphabet ('z' goes to 'a' and 'Z' goes to 'A').
    - Digits (0-9) are replaced by their complement to 9 (e.g., '0' with '9', '1' with '8').
    - All other characters remain unchanged.
    """
    transformed = []
    for char in s:
        if char.isalpha():
            if char == 'z':
                transformed.append('a')
            elif char == 'Z':
                transformed.append('A')
            else:
                transformed.append(chr(ord(char) + 1))
        elif char.isdigit():
            transformed.append(str(9 - int(char)))
        else:
            transformed.append(char)
    return ''.join(transformed)

