def find_duplicate_values_with_keys(input_dict):
    """
    Function to find and return duplicate values with their associated keys.

    :param input_dict: dict
    :return: dict containing duplicate values with their associated keys
    """
    if not isinstance(input_dict, dict):
        raise TypeError("Input must be a dictionary")

    value_to_keys = {}
    duplicates = {}

    for key, value in input_dict.items():
        if value in value_to_keys:
            if value not in duplicates:
                duplicates[value] = [value_to_keys[value]]
            duplicates[value].append(key)
        else:
            value_to_keys[value] = key

    return duplicates

