def power(base_number, exp_number):
    """
    Calculates the power of base_number to exp_number using recursion.
    """
    if exp_number == 0:
        return 1
    elif exp_number < 0:
        return 1 / power(base_number, -exp_number)
    else:
        return base_number * power(base_number, exp_number - 1)

