def generate_primes(n):
    """
    Returns a list of all prime numbers less than n.
    """
    if n <= 2:
        return []

    primes = []
    is_prime = [True] * n

    for number in range(2, n):
        if is_prime[number]:
            primes.append(number)
            for multiple in range(number * number, n, number):
                is_prime[multiple] = False

    return primes

