def longestPalindrome(s: str) -> int:
    from collections import Counter

    char_count = Counter(s)
    length = 0
    odd_found = False

    for count in char_count.values():
        if count % 2 == 0:
            length += count
        else:
            length += count - 1
            odd_found = True

    if odd_found:
        length += 1

    return length

