def character_frequency(s):
    """
    Returns the frequency of each character in the given string as a dictionary.
    Whitespace characters are ignored.
    """
    frequency = {}
    for char in s:
        if not char.isspace():
            frequency[char] = frequency.get(char, 0) + 1
    return frequency

