from typing import List, Tuple

def search_in_sorted_matrix(mat: List[List[int]], target: int) -> Tuple[int, int]:
    if not mat or not mat[0]:
        return -1, -1  # Handle empty matrix case

    m, n = len(mat), len(mat[0])
    i, j = 0, n - 1  # Start from the top-right corner

    while i < m and j >= 0:
        if mat[i][j] == target:
            return i, j  # Target found
        elif mat[i][j] > target:
            j -= 1  # Move left
        else:
            i += 1  # Move down
    return -1, -1  # Target not found

