def length_of_longest_substring(s):
    """
    Returns the length of the longest substring of `s` that does not contain any repeating characters.
    If `s` is empty or does not contain any unique characters, returns 0.
    """
    if not s:
        return 0

    start = 0
    max_length = 0
    char_index_map = {}

    for end in range(len(s)):
        if s[end] in char_index_map:
            start = max(start, char_index_map[s[end]] + 1)

        char_index_map[s[end]] = end
        max_length = max(max_length, end - start + 1)

    return max_length

