def longest_contiguous_subsequence(arr: list[int]) -> tuple[int, int, int]:
    if not arr:
        return (0, 0, -1)

    max_value = arr[0]
    max_length = 1
    max_start_index = 0

    current_value = arr[0]
    current_length = 1
    current_start_index = 0

    for i in range(1, len(arr)):
        if arr[i] == current_value:
            current_length += 1
        else:
            if current_length > max_length:
                max_value = current_value
                max_length = current_length
                max_start_index = current_start_index
            current_value = arr[i]
            current_length = 1
            current_start_index = i

    if current_length > max_length:
        max_value = current_value
        max_length = current_length
        max_start_index = current_start_index

    return (max_value, max_length, max_start_index)

import math

def factorial(n):
    """
    Returns the factorial of a number n. 
    Handles large inputs by using math.factorial which manages big integers.
    Raises ValueError for negative numbers and TypeError for non-integer types.
    """
    if not isinstance(n, int):
        raise TypeError("Input must be an integer.")
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")

    return math.factorial(n)

