def is_valid_variable_name(variable_name: str) -> bool:
    """
    Checks if the input string is a valid variable name in Python.
    """
    if not variable_name:
        return False
    if variable_name[0].isdigit():
        return False
    if variable_name in keyword.kwlist:
        return False
    if not all(char.isalnum() or char == '_' for char in variable_name):
