def findWays(n):
    MOD = 1000000007

    if n == 1:
        return 1
    elif n == 2:
        return 2
    elif n == 3:
        return 4

    ways = [0] * (n + 1)
    ways[1], ways[2], ways[3] = 1, 2, 4

    for i in range(4, n + 1):
        ways[i] = (ways[i-1] + ways[i-2] + ways[i-3]) % MOD

    return ways[n]

