def bubble_sort(arr):
    """
    This function implements the bubble sort algorithm.
    It sorts the provided list `arr` in ascending order.
    """
    n = len(arr)
    for i in range(n):
        for j in range(0, n - i - 1):
            if arr[j] > arr[j + 1]:
                # Swap the elements
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
    return arr

