def modify_values(dictionary, defaults, path=None):
    if path is None:
        path = []
    result = dictionary.copy()
    for key, value in defaults.items():
        current_path = path + [key]
        if isinstance(value, dict):
            if key in result and isinstance(result[key], dict):
                result[key] = modify_values(result[key], value, current_path)
            else:
                result[key] = value
        else:
            result[key] = value
