from typing import List

def max_profit(n: int, prices: List[int]) -> int:
    if n < 2:
        return 0

    min_price = prices[0]
    max_profit = 0

    for i in range(1, n):
        min_price = min(min_price, prices[i])
        max_profit = max(max_profit, prices[i] - min_price)

    return max_profit

