def transform_json(json_data, key_mapping):
    """
    Transforms the given JSON data according to the provided key mappings.

    :param json_data: The JSON data to be transformed (as a dictionary).
    :param key_mapping: A dictionary with key mappings where the keys are the original keys and the values are the desired keys.
    :return: A new dictionary with the transformed keys.
    """
    new_json_data = {}
    for key, value in json_data.items():
        if key in key_mapping:
            new_key = key_mapping[key]
        else:
            new_key = key
        if isinstance(value, dict):
            new_json_data[new_key] = transform_json(value, key_mapping)
        else:
            new_json_data[new_key] = value
    return new_json_data

