from typing import List

def optimized_exchange_sort(arr: List[int]) -> List[int]:
    """
    Sorts an array using an optimized version of the Exchange Sort algorithm.
    """
    n = len(arr)
    if n <= 1:
        return arr

    for i in range(n):
        swapped = False
        for j in range(n - 1, i, -1):
            if arr[j-1] > arr[j]:
                arr[j-1], arr[j] = arr[j], arr[j-1]
                swapped = True
        if not swapped:
            # If no elements were swapped, the array is already sorted
            break

    return arr

