def find_first_non_repeating_char(s: str) -> str:
    """
    Identifies the first non-repeating character in a given string.
    If all characters are repeating, returns an underscore ('_').

    Parameters:
    s (str): The string to be processed.

    Returns:
    str: The first non-repeating character or '_' if all characters are repeating.
    """
    char_count = {}

    # First pass: count occurrences of each character
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Second pass: find the first character with a count of 1
    for char in s:
        if char_count[char] == 1:
            return char

    return '_'

