def minOperations(num1, num2):
    operations = 0
    while num1 > 0:
        if num2 == 0:
            return -1
        k = 0
        while (1 << (k+1)) <= num1:
            k += 1
        num1 -= (1 << k)
        num2 -= 1
        operations += 1

    return operations

