def longestSubarray(arr, n, k):
    """
    Given an array `arr` and an integer `k`, returns the longest subarray where the sum is divisible by `k`.
    If multiple subarrays have the same length, returns the one with the smallest starting index.
    """
    # Dictionary to store {mod: index}
    mod_dict = {0: -1}
    max_len = 0
    start_idx = -1
    current_sum = 0

    for i in range(n):
        current_sum += arr[i]
        mod = current_sum % k

        if mod < 0:
            mod += k

        if mod in mod_dict:
            if i - mod_dict[mod] > max_len:
                max_len = i - mod_dict[mod]
                start_idx = mod_dict[mod] + 1
        else:
            mod_dict[mod] = i

    if start_idx == -1:
        return []
    return arr[start_idx:start_idx + max_len]

