from typing import List

def maxProfit(prices: List[int], n: int) -> int:
    if n < 2:
        return 0

    min_price = prices[0]
    max_profit = 0

    for i in range(1, n):
        if prices[i] < min_price:
            min_price = prices[i]
        else:
            profit = prices[i] - min_price
            if profit > max_profit:
                max_profit = profit

    return max_profit

def compress_string(s):
    """
    Takes a string as input and returns a new string where consecutive occurrences of the 
    same character are replaced with that character followed by the count of duplicates.
    """
    if not s:
        return ""

    compressed = []
    count = 1
    last_char = s[0]

    for char in s[1:]:
        if char == last_char:
            count += 1
        else:
            compressed.append(f"{last_char}{count}")
            last_char = char
            count = 1

    compressed.append(f"{last_char}{count}")

    return ''.join(compressed)

