import math

def min_num_perfect_squares(n):
    """
    Returns the smallest number of perfect squares that sum to the specified number.

    :param n: int, the number to be summed to using smallest number of perfect squares
    :return: int between 1 - 4, the minimum number of perfect squares that sum to the specified number
    """
    if int(math.sqrt(n))**2 == n:
        return 1

    while n > 0 and n % 4 == 0:
        n = n // 4

    if n % 8 == 7:
        return 4

    for i in range(1, int(math.sqrt(n)) + 1):
        if int(math.sqrt(n - i**2))**2 == n - i**2:
            return 2

    return 3

def compress_string(input_string: str) -> str:
    if not input_string:
        return ""

    compressed = []
    count = 1

    for i in range(1, len(input_string)):
        if input_string[i] == input_string[i - 1]:
            count += 1
        else:
            compressed.append(input_string[i - 1] + str(count))
            count = 1

    compressed.append(input_string[-1] + str(count))

    compressed_string = ''.join(compressed)

    return compressed_string if len(compressed_string) < len(input_string) else input_string

