def majority_element(nums):
    """
    Finds the majority element in the list. The majority element is the element that appears 
    more than n // 2 times, where n is the size of the list. Returns None if no majority element exists.
    """
    element_count = {}
    n = len(nums)

    for num in nums:
        if num in element_count:
            element_count[num] += 1
        else:
            element_count[num] = 1

        if element_count[num] > n // 2:
            return num

    return None

