def unique_elements(arr):
    """
    Returns a sorted list of elements that appear only once in the given array.
    """
    element_count = {}
    for elem in arr:
        if elem in element_count:
            element_count[elem] += 1
        else:
            element_count[elem] = 1

    unique_elems = [elem for elem in element_count if element_count[elem] == 1]
    unique_elems.sort()

    return unique_elems

