def smallest_substring_with_k_distinct(s, k):
    """
    Returns the length of the smallest substring of 's' that contains at least 'k' distinct characters.
    If no such substring exists, return -1.
    """
    if k > len(set(s)):
        return -1

    n = len(s)
    min_length = n + 1
    left = 0
    char_map = {}

    for right in range(n):
        char_map[s[right]] = char_map.get(s[right], 0) + 1

        while len(char_map) >= k:
            min_length = min(min_length, right - left + 1)
            char_map[s[left]] -= 1
            if char_map[s[left]] == 0:
                del char_map[s[left]]
            left += 1

    return min_length if min_length <= n else -1

