def balanced_brackets(s: str) -> bool:
    """
    Returns True if the string `s` contains balanced brackets.
    Otherwise returns False.
    """
    stack = []
    bracket_map = {')': '(', ']': '[', '}': '{'}

    for char in s:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map.keys():
            if stack == [] or bracket_map[char] != stack.pop():
                return False
        else:
            continue

    return stack == []

