def longest_subarray_with_sum(nums, target):
    """
    Returns the longest contiguous subarray whose sum is equal to the target.
    If there is no such subarray, returns an empty array.
    """
    sum_map = {0: -1}
    current_sum = 0
    max_length = 0
    subarray_start = -1

    for index, num in enumerate(nums):
        current_sum += num

        if current_sum - target in sum_map:
            if index - sum_map[current_sum - target] > max_length:
                max_length = index - sum_map[current_sum - target]
                subarray_start = sum_map[current_sum - target] + 1

        if current_sum not in sum_map:
            sum_map[current_sum] = index

    if max_length == 0:
        return []

    return nums[subarray_start:subarray_start + max_length]

