reference_solution:
def count_repeated_characters(sentence):
    """
    Returns a dictionary with characters as keys and their counts as values,
    only for characters that are repeated in the sentence.
    """
    char_count = {}
    for char in sentence:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Filter out characters that are not repeated
    repeated_chars = {char: count for char, count in char_count.items() if count > 1}

    return repeated_chars

import math

def getPrimeNumbers(n):
    """
    Returns a list of all prime numbers up to and including n.
    """
    primes = []
    if n < 2:
        return primes

    # Create a boolean array "prime[0..n]" and initialize all entries it as true.
    prime = [True for _ in range(n+1)]
    p = 2
    while p * p <= n:
        if prime[p] == True:
            for i in range(p * p, n + 1, p):
                prime[i] = False
        p += 1

    for p in range(2, n + 1):
        if prime[p]:
            primes.append(p)

    return primes

