def is_prime(n):
    """
    Determines whether a given integer n is a prime number.

    :param n: Integer to check
    :return: True if n is a prime number, False otherwise
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def is_multiple_of_3(n):
