def length_of_lis(nums):
    """
    Finds the length of the longest increasing subsequence in a given list of integers using dynamic programming.

    Args:
    nums: List[int] - A list of integers.

    Returns:
    int - Length of the longest increasing subsequence.
    """
    if not nums:
        return 0

    n = len(nums)
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

