from typing import List

def find_longest_common_prefix(strings: List[str]) -> str:
    if not strings:
        return ""

    # Initialize to the first string since we need to compare others to it
    prefix = strings[0]

    for i in range(1, len(strings)):
        temp_prefix = ""
        for j in range(min(len(prefix), len(strings[i]))):
            if prefix[j] == strings[i][j]:
                temp_prefix += prefix[j]
            else:
                break
        prefix = temp_prefix

        # If at any point, the common prefix becomes empty, return immediately
        if prefix == "":
            return ""

    return prefix

