import bisect

def process_transactions(transactions):
    sorted_transactions = []
    medians = []

    for t in transactions:
        bisect.insort(sorted_transactions, t)
        n = len(sorted_transactions)
        if n % 2 == 1:
            medians.append(float(sorted_transactions[n // 2]))
        else:
            medians.append((sorted_transactions[n // 2 - 1] + sorted_transactions[n // 2]) / 2)

    return medians

