def find_duplicates(lst):
    """
    Returns a list of duplicates in the input list lst.
    """
    seen = set()
    duplicates = set()
    for item in lst:
        if item in seen:
            duplicates.add(item)
        else:
            seen.add(item)
    return list(duplicates)

