reference_solution:
def modify_list(lst, operation):
    operations = {
        "add": lambda x: x + 1,
        "subtract": lambda x: x - 1,
        "none": lambda x: x
    }

    if operation not in operations:
        raise ValueError("Invalid operation")

    return [operations[operation](x) for x in lst]

