reference_solution:
def edit_distance(str1: str, str2: str) -> int:
    # Get the lengths of both strings
    len1, len2 = len(str1), len(str2)

    # Initialize a DP table where dp[i][j] represents the edit distance
    # between str1[0..i-1] and str2[0..j-1]
    dp = [[0 for _ in range(len2 + 1)] for _ in range(len1 + 1)]

    # Fill dp table for the base case: transforming an empty string to another
    for i in range(len1 + 1):
        dp[i][0] = i  # i insertions to transform str1 to empty str2
    for j in range(len2 + 1):
        dp[0][j] = j  # j insertions to transform empty str1 to str2

    # Fill the dp table for all other cases
    for i in range(1, len1 + 1):
        for j in range(1, len2 + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = min(
                    dp[i - 1][j] + 1,    # Deletion
                    dp[i][j - 1] + 1,    # Insertion
                    dp[i - 1][j - 1] + 1 # Substitution
                )

    return dp[len1][len2]

