def rotate_image(matrix):
    """
    Rotates the given n x n matrix by 90 degrees clockwise in-place.
    """
    # First, transpose the matrix
    n = len(matrix)
    for i in range(n):
        for j in range(i, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]

    # Then, reverse each row
    for i in range(n):
        matrix[i].reverse()

