reference_solution:
def nearest_person(houses):
    N = len(houses)
    distances = [float('inf')] * N

    # Forward pass to find distances to the nearest person to the left (or self)
    last_person_index = -1
    for i in range(N):
        if houses[i] == 1:
            last_person_index = i
        if last_person_index != -1:
            distances[i] = i - last_person_index

    # Backward pass to find distances to the nearest person to the right
    last_person_index = -1
    for i in range(N-1, -1, -1):
        if houses[i] == 1:
            last_person_index = i
        if last_person_index != -1:
            distances[i] = min(distances[i], last_person_index - i)

    return distances

