def canPartition(arr, N):
    """
    Determine if it's possible to partition the array into two groups with equal sum.
    """
    total_sum = sum(arr)

    # If total sum is odd, it cannot be partitioned into two equal subsets
    if total_sum % 2 != 0:
        return False

    target = total_sum // 2
    dp = [[False] * (target + 1) for _ in range(N + 1)]

    # Initialize the dp array
    for i in range(N + 1):
        dp[i][0] = True

    for i in range(1, N + 1):
        for j in range(1, target + 1):
            if arr[i - 1] <= j:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - arr[i - 1]]
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[N][target]

def shiftString(s, k):
    """
    Shifts each character in the string `s` by `k` positions in the alphabet.
    """
    result = []
    for char in s:
        new_char = chr(((ord(char) - ord('a') + k) % 26) + ord('a'))
        result.append(new_char)
    return ''.join(result)

