def longest_common_subsequence(X, Y):
    """
    Returns the length of the longest common subsequence between two sequences X and Y.
    """
    m = len(X)
    n = len(Y)

    # Create a 2D array to store lengths of longest common subsequence.
    dp = [[0] * (n + 1) for i in range(m + 1)]

    # Build the dp array from the bottom up
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 or j == 0:
                dp[i][j] = 0
            elif X[i - 1] == Y[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[m][n]

