def topKFrequent(nums):
    """
    Returns elements of `nums` sorted by frequency in descending order.
    Each element in the resulting list is a list containing the element and its frequency.
    """
    # Step 1: Count frequency of each number using a hashmap
    count = {}
    for num in nums:
        if num not in count:
            count[num] = 0 
        count[num] += 1

    # Step 2: Create bucket array where index represents frequency
    bucket = [[] for _ in range(len(nums) + 1)]

    # Step 3: Distribute elements into their respective buckets
    for num, freq in count.items():
        bucket[freq].append(num)

    # Step 4: Sort the bucket in descending order of frequency and combine elements of the same frequency
    sort_bucket = []
    for i in range(len(bucket)-1, 0, -1):
        if bucket[i]:
            for num in bucket[i]:
                sort_bucket.append([num, i])

    return sort_bucket

